const sourcedCardSeeds: SourcedCardSeed[] = Object.values(sourcedCardsBySeries).flat();

export const cards: Card[] = sourcedCardSeeds.map((source) => ({
  id: `ccg-${source.sourceSet.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-${source.number
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")}`,
  number: source.number,
  rarity: source.rarity as Card["rarity"],
  character: source.character,
  name: {
    en: source.character,
    // No translations are invented; source English label is retained as fallback text.
    zh: source.character,
    ja: source.character,
  },
  image: source.imageFile.startsWith("http")
    ? source.imageFile
    : `${SOURCE_IMAGE_BASE}${source.imageFile}`,
  isPlaceholder: false,
  flavor: {
    en: `Community-sourced card record. Source series/set reference: ${source.sourceSet}.`,
    zh: `Community-sourced card record. Source series/set reference: ${source.sourceSet}.`,
    ja: `Community-sourced card record. Source series/set reference: ${source.sourceSet}.`,
  },
  marketRegion: "UNKNOWN",
  printLanguage: "Unknown",
  sourceStatus: "Community sourced" as Card["sourceStatus"],
  recordStatus: "community_sourced" as Card["recordStatus"],
  imageStatus: "source_reference" as Card["imageStatus"],
  priceStatus: "unavailable" as Card["priceStatus"],
  sourceNotes: [
    `Indexed from Capsule Corp Gear. Source series/set reference: ${source.sourceSet}.`,
    "This source set reference is not an exclusivity or guaranteed pull-location claim.",
    source.sourceMetadata ? `Source metadata: ${source.sourceMetadata}.` : undefined,
    `Source page: ${SOURCE_PAGE}`,
  ]
    .filter(Boolean)
    .join(" "),
}));

// Regression safeguards against partial imports or accidental duplicate cards.
const uniqueCardNumbers = new Set(cards.map((card) => card.number));
if (uniqueCardNumbers.size !== cards.length) {
  throw new Error("Duplicate card number detected in sourced ShinobIndex catalogue.");
}
if (cards.length !== STORE_READY_UNIQUE_CARD_COUNT) {
  throw new Error(
    `Sourced ShinobIndex catalogue expected ${STORE_READY_UNIQUE_CARD_COUNT} unique cards, found ${cards.length}.`
  );
}
